import{c as t,Q as i,j as o,m as n}from"./chunks/framework.BPKcPtvA.js";const m=JSON.parse('{"title":"Profil Layanan PPPoE","description":"","frontmatter":{},"headers":[],"relativePath":"panduan/pppoe/profil.md","filePath":"panduan/pppoe/profil.md"}'),r={name:"panduan/pppoe/profil.md"};function e(l,a,d,s,p,u){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="profil-layanan-pppoe" tabindex="-1">Profil Layanan PPPoE <a class="header-anchor" href="#profil-layanan-pppoe" aria-label="Permalink to &quot;Profil Layanan PPPoE&quot;">​</a></h1><p>Profil layanan mendefinisikan <strong>paket internet</strong> yang bisa Anda tawarkan ke pelanggan — kecepatan, harga, dan konfigurasi MikroTik terkait.</p><hr><h2 id="membuat-profil-baru" tabindex="-1">Membuat Profil Baru <a class="header-anchor" href="#membuat-profil-baru" aria-label="Permalink to &quot;Membuat Profil Baru&quot;">​</a></h2><ol><li>Buka router yang diinginkan</li><li>Di sidebar, pilih <strong>PPPoE → Profil Layanan</strong></li><li>Klik <strong>+ Tambah Profil</strong></li><li>Isi form berikut:</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Nama Profil</strong></td><td>Nama profil di MikroTik, misal <code>10Mbps</code></td></tr><tr><td><strong>Nama Layanan</strong></td><td>Nama paket yang tampil ke pelanggan, misal <code>Paket Silver 10 Mbps</code></td></tr><tr><td><strong>Upload Max</strong></td><td>Batas kecepatan upload, misal <code>10M</code></td></tr><tr><td><strong>Download Max</strong></td><td>Batas kecepatan download, misal <code>10M</code></td></tr><tr><td><strong>Harga Saran</strong></td><td>Harga default untuk tagihan bulanan (Rp)</td></tr><tr><td><strong>PPN</strong></td><td>Persentase PPN yang ditambahkan ke tagihan (opsional, misal <code>11</code>)</td></tr></tbody></table><ol start="5"><li>Klik <strong>Simpan</strong></li></ol><p>Profil akan otomatis di-sync ke PPPoE Profile di router MikroTik.</p><hr><h2 id="rate-limit-format" tabindex="-1">Rate Limit Format <a class="header-anchor" href="#rate-limit-format" aria-label="Permalink to &quot;Rate Limit Format&quot;">​</a></h2><p>Eznom menggunakan format rate limit MikroTik standar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>upload/download</span></span></code></pre></div><p>Contoh:</p><ul><li><code>5M/10M</code> → upload 5 Mbps, download 10 Mbps</li><li><code>10M/10M</code> → simetris 10 Mbps</li><li><code>1M/2M</code> → upload 1 Mbps, download 2 Mbps</li></ul><hr><h2 id="edit-hapus-profil" tabindex="-1">Edit &amp; Hapus Profil <a class="header-anchor" href="#edit-hapus-profil" aria-label="Permalink to &quot;Edit &amp; Hapus Profil&quot;">​</a></h2><ul><li>Klik ikon <strong>pensil</strong> di baris profil untuk mengedit</li><li>Klik ikon <strong>hapus</strong> untuk menghapus profil</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Profil yang sedang digunakan pelanggan aktif tidak bisa dihapus. Pindahkan pelanggan ke profil lain terlebih dahulu.</p></div>',18)])])}const c=t(r,[["render",e]]);export{m as __pageData,c as default};
